+// OTHRYSL2-023 Multi-list manager
+
+import { promises as fs } from 'fs';
+import { join } from 'path';
+
+export async function createMultiListStore(filePath) {
+  const file = join(filePath);
+
+  async function snapshot() {
+    try {
+      const data = await fs.readFile(file, 'utf-8');
+      const parsed = JSON.parse(data);
+      return parsed;
+    } catch (e) {
+      if (e.code === 'ENOENT') {
+        return { lists: [] };
+      } else {
+        throw new Error('STATE_CORRUPT');
+      }
+    }
+  }
+
+  async function createList(list) {
+    const current = await snapshot();
+    const listId = list.id;
+
+    if (current.lists.some(l => l.id === listId)) {
+      throw new Error('DUPLICATE_ID');
+    }
+
+    const newList = {
+      id: list.id,
+      name: list.name,
+      items: list.items || []
+    };
+
+    const updated = {
+      lists: [...current.lists, newList]
+    };
+
+    await writeData(updated);
+    return JSON.parse(JSON.stringify(newList));
+  }
+
+  async function renameList(listId, newName) {
+    const current = await snapshot();
+
+    const list = current.lists.find(l => l.id === listId);
+    if (!list) {
+      throw new Error('NOT_FOUND');
+    }
+
+    list.name = newName;
+
+    const updated = {
+      lists: current.lists
+    };
+
+    await writeData(updated);
+    return JSON.parse(JSON.stringify(list));
+  }
+
+  async function deleteList(listId) {
+    const current = await snapshot();
+
+    const list = current.lists.find(l => l.id === listId);
+    if (!list) {
+      throw new Error('NOT_FOUND');
+    }
+
+    const updated = {
+      lists: current.lists.filter(l => l.id !== listId)
+    };
+
+    await writeData(updated);
+    return JSON.parse(JSON.stringify(list));
+  }
+
+  async function addItem(listId, item) {
+    const current = await snapshot();
+
+    const list = current.lists.find(l => l.id === listId);
+    if (!list) {
+      throw new Error('NOT_FOUND');
+    }
+
+    const newItem = {
+      id: item.id,
+      text: item.text,
+      done: item.done || false
+    };
+
+    if (list.items.some(i => i.id === newItem.id)) {
+      throw new Error('DUPLICATE_ID');
+    }
+
+    list.items.push(newItem);
+
+    const updated = {
+      lists: current.lists
+    };
+
+    await writeData(updated);
+    return JSON.parse(JSON.stringify(newItem));
+  }
+
+  async function updateItem(listId, itemId, update) {
+    const current = await snapshot();
+
+    const list = current.lists.find(l => l.id === listId);
+    if (!list) {
+      throw new Error('NOT_FOUND');
+    }
+
+    const item = list.items.find(i => i.id === itemId);
+    if (!item) {
+      throw new Error('NOT_FOUND');
+    }
+
+    if (update.text !== undefined) {
+      item.text = update.text;
+    }
+
+    if (update.done !== undefined) {
+      item.done = update.done;
+    }
+
+    const updated = {
+      lists: current.lists
+    };
+
+    await writeData(updated);
+    return JSON.parse(JSON.stringify(item));
+  }
+
+  async function removeItem(listId, itemId) {
+    const current = await snapshot();
+
+    const list = current.lists.find(l => l.id === listId);
+    if (!list) {
+      throw new Error('NOTFOUND');
+    }
+
+    const itemIndex = list.items.findIndex(i => i.id === itemId);
+    if (itemIndex === -1) {
+      throw new Error('NOT_FOUND');
+    }
+
+    list.items.splice(itemIndex, 1);
+
+    const updated = {
+      lists: current.lists
+    };
+
+    await writeData(updated);
+    return JSON.parse(JSON.stringify(list));
+  }
+
+  async function writeData(data) {
+    try {
+      await fs.writeFile(file, JSON.stringify(data, null, 2), 'utf-8');
+    } catch (e) {
+      throw new Error('STATE_CORRUPT');
+    }
+  }
+
+  return {
+    snapshot,
+    createList,
+    renameList,
+    deleteList,
+    addItem,
+    updateItem,
+    removeItem
+  };
+}

